def restore_kanto_interiors_text(path, source):
    if str(path)!="src/data/wild_encounters.json":return source
    for label, old in ORIGINAL_KANTO_INTERIORS.items():
        marker='"base_label": "'+label+'"' 
        i=source.index('"mons": [',source.index(marker))
        current=BALANCED_KANTO_INTERIORS[label]
        assert source[i:i+len(current)]==current,label
        source=source[:i]+old+source[i+len(current):]
    return source

def prior_kanto_interiors_source(path):
    return restore_kanto_interiors_text(path,prior_kanto_central_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_kanto_interiors_text(path,source):
    return restore_kanto_interiors_text(path,restore_prior_kanto_central_text(path,source))
